async function boot(){await TNT.ready;if(!TNT.identity||TNT.blocked)return;S.account=TNT.account;S.person=TNT.person;S.session=TNT.session;loading();await loadAll();readDeepLink();initOrgHistory();render();openDeepLink();startOrgUpdates();}

async function initAuthed(){await boot();}

async function loadAll(){
 const version=++orgLoadVersion,data={},errors=[];
 const tables={people:'tnt_people',accounts:'tnt_accounts',events:'tnt_events',eventMembers:'tnt_event_members',tasks:'tnt_tasks',assignees:'tnt_task_assignees',templates:'tnt_templates',templateItems:'tnt_template_items',days:'tnt_schedule_days',items:'tnt_schedule_items',responsibles:'tnt_schedule_responsibles',groups:'tnt_groups',groupMembers:'tnt_group_members',groupConfigs:'tnt_group_configs',notifications:'tnt_notifications',availability:'tnt_availability',workload:'tnt_monthly_workload',moduleAccess:'tnt_module_access',files:'tnt_library_items',settings:'tnt_settings',checkins:'tnt_checkins'};
 await Promise.all(Object.entries(tables).map(async([key,table])=>{try{let q=sb.from(table).select('*');if(key==='notifications'&&window.TNTNotifications){data[key]=await TNTNotifications.load();return;}if(key==='notifications')q=q.order('created_at',{ascending:false}).limit(100);const r=await q;if(r.error)throw r.error;data[key]=(r.data||[]).filter(row=>!row.archived_at);}catch(e){errors.push(key);console.warn('Organización: '+key,e);}}));
 if(version!==orgLoadVersion)return;
 Object.assign(S,data);S.errors=errors;pruneOrgState();
 S.people=S.people.map(p=>({...p,full_name:U.personName(p.full_name)}));S.people.sort((a,b)=>a.full_name.localeCompare(b.full_name));S.events.sort((a,b)=>a.start_date.localeCompare(b.start_date));S.account=S.accounts.find(a=>a.person_id===TNT.person.id)||TNT.account;S.person=S.people.find(p=>p.id===TNT.person.id)||TNT.person;
 if(!eventBy(S.selectedEvent))S.selectedEvent=S.events.find(e=>e.end_date>=today()&&e.status!=='cancelled')?.id||S.events.find(e=>e.status!=='cancelled')?.id||null;
 if(!eventDays(S.selectedEvent).some(d=>d.id===S.selectedDay))S.selectedDay=eventDays(S.selectedEvent)[0]?.id||null;
}
function readDeepLink(){const q=new URLSearchParams(location.search);S.view=q.get('view')||'my';if(q.get('date'))S.calendarDate=/^\d{4}-\d{2}-\d{2}$/.test(q.get('date'))?q.get('date'):today();if(q.get('task'))S.view='activities';if(q.get('event')){S.view=q.get('view')==='schedule'?'schedule':'events';S.selectedEvent=q.get('event');}if(q.get('person'))S.view='team';if(S.calendarDate)S.calendarMonth=S.calendarDate.slice(0,7)+'-01';}

function navButtons(mobile=false){let arr=[...NAV];if(isAdmin())arr.push(['admin','⚙','Admin']);return arr.map(([id,ico,label])=>`<button class="navBtn ${S.view===id?'on':''} ${id==='admin'?'admin':''}" data-view="${id}"><span class="ni">${ico}</span><span>${label}</span></button>`).join('')}
function shell(content,title){const nav=[['my','home','Mi TNT'],['saturdays','calendar','Encuentros'],['calendar','calendar','Calendario'],['schedule','clock','Cronograma'],['team','people','Equipo'],['templates','book','Plantillas'],['files','file','Archivos']];return `<div class="org-shell"><header class="org-heading"><div><div class="eyebrow">EQUIPO TNT</div><h1>${S.view==='my'?'Mi organización':esc(title)}</h1><p>${S.view==='my'?'Lo que compartimos y lo que te toca.':'Planificamos juntos lo que viene.'}</p></div><div class="actions"><button class="btn schedule-direct" data-quick-schedule>${U.icon('clock')}<span>Cronograma rápido</span></button><button class="btn" data-open-chat>${U.icon('chat')}<span>Chat</span></button></div></header><nav class="org-nav" aria-label="Organización"><div class="org-nav-track">${nav.map(([k,ico,l])=>`<button class="${(['activities','tasks','events'].includes(S.view)?'saturdays':S.view)===k?'on':''}" data-view="${k}" aria-current="${(['activities','tasks','events'].includes(S.view)?'saturdays':S.view)===k?'page':'false'}">${U.icon(ico)}<span>${l}</span><i aria-hidden="true"></i></button>`).join('')}</div></nav>${S.errors?.length?'<div class="tnt-error" role="alert">No pudimos actualizar algunos datos. <button class="btn" data-reload>Reintentar</button></div>':''}${S.recurringError?'<div class="tnt-error" role="alert">'+esc(S.recurringError)+'</div>':''}${content}</div>`;}
function render(){if(window.TNTScheduleOrder?.busy)return;const views={my:()=>[viewMy(),'Mi TNT'],calendar:()=>[viewCalendar(),'Calendario'],saturdays:()=>[viewActivities(),'Encuentros'],activities:()=>[viewActivities(),'Encuentros'],tasks:()=>[viewActivities(),'Encuentros'],events:()=>[viewEvents(),'Eventos'],team:()=>[viewTeam(),'Equipo'],templates:()=>[viewTemplates(),'Plantillas'],schedule:()=>[viewSchedule(),'Cronograma y grupos'],files:()=>[viewFiles(),'Archivos'],brief:()=>[viewBrief(),'Mi resumen'],admin:()=>[viewAdmin(),'Administración']};const [html,title]=(views[S.view]||views.my)();const x=$('.org-nav-track')?.scrollLeft||0;$('#app').innerHTML=shell(html,title);if($('.org-nav-track'))$('.org-nav-track').scrollLeft=x;bindGlobal();bindViewSpecific();bindNew();bindActivityActions();bindActivitySwipes();bindScheduleOrder();}
function bindGlobal(){
 $$('[data-view]').forEach(b=>b.onclick=()=>navigateView(b.dataset.view));
 $$('[data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action,b));
 $$('[data-event-open]').forEach(b=>b.onclick=()=>openEncounter(b.dataset.eventOpen));
 $$('[data-task-open]').forEach(b=>b.onclick=()=>taskDetailModal(b.dataset.taskOpen));
 $$('[data-person-open]').forEach(b=>b.onclick=()=>personResponsibilitiesModal(b.dataset.personOpen));
 $$('[data-quick-schedule]').forEach(b=>b.onclick=openQuickSchedule);
}
async function handleAction(a,b){
  if(a==='signout')return sb.auth.signOut();if(a==='profile')return TNT.editProfile();if(a==='notifications')return notificationsModal();
  if(a==='browse-saturdays')return navigateView('saturdays');if(a==='new-saturday')return saturdayCreateModal();if(a==='new-event')return eventCreateModal();if(a==='invite-staff')return inviteStaffModal();
  if(a==='new-template')return templateModal();if(a==='general-notification')return generalNotificationModal();
  if(a==='group-config')return groupConfigModal(S.selectedDay);if(a==='event-members')return eventMembersModal(S.selectedEvent);
}


/* organizacion/app2.js */
function viewMy() {
 const tasks=personalTasks(),items=personalItems(),events=coordinatedEvents(),total=tasks.length+items.length+events.length;
 const next=S.events.filter(e=>(e.end_date||e.start_date)>=today()&&e.status!=='cancelled').sort((a,b)=>a.start_date.localeCompare(b.start_date)).slice(0,3);
 return `<section class="my-summary"><div><span class="eyebrow">${esc(displayName(currentPersonId()))}</span><h2>${S.errors.length?'Actualizando tu espacio':total?'Tu lugar en el equipo.':'Tu equipo te espera.'}</h2><p>${events.length?'Coordinás '+events.length+' '+(events.length===1?'encuentro':'encuentros')+'. ':''}${tasks.length+items.length?tasks.length+items.length+' actividades a tu cargo.':'Acá encontrás tus próximas responsabilidades.'}</p><button class="btn" data-view="brief">Ver mi resumen ${U.icon('arrow')}</button></div>${avatarHtml(currentPersonId())}</section><div class="sectionHead"><h2>Mis responsabilidades</h2><button class="btn small" data-view="saturdays">Ver encuentros</button></div><div class="activities-grid">${tasks.map(t=>taskRow(t,myAssignment(t))).join('')}${items.map(i=>scheduleItemRow(eventBy(dayBy(i.day_id).event_id),i)).join('')}${!tasks.length&&!items.length?empty('Sin actividades asignadas','Cuando te asignen una actividad, aparecerá acá.'):''}</div><div class="sectionHead"><h2>Lo que viene</h2><button class="btn small" data-view="calendar">Calendario</button></div><div class="grid g3">${next.map(eventCard).join('')||empty('Sin eventos próximos','')}</div>`;
}
function taskRow(t,a){
 const e=eventBy(t.event_id),mine=Boolean(myAssignment(t)&&myAssignment(t).assignment_status!=='declined'),ids=taskPeople(t.id),date=t.planned_start||t.due_at;
 const count=ids.length?`${ids.length} ${ids.length===1?'responsable':'responsables'}`:canSeePlanningGaps(t.event_id)?'Sin responsable':'';
 return `<article class="activity-card ${mine?'is-mine':''} ${t.is_featured?'is-featured':''}" style="--activity-color:${['var(--tnt-lime)','var(--tnt-peach)','var(--tnt-blue)'][Math.abs(t.sort_order||0)%3]};${featureStyle(t)}"><button class="activity-card-main" data-task-open="${t.id}"><div class="activity-top"><span class="activity-time">${date?U.icon('clock')+' '+U.date(date,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):esc(e?fmtDate(e.start_date):'')}</span>${mine?'<span class="part-badge">'+U.icon('check')+' Sos parte</span>':''}</div><div class="activity-tags"><span>${esc(ACTIVITY_TYPES[activityType(t)])}</span>${featuredBadge(t)}</div><h3>${esc(t.title)}</h3>${e?.kind==='saturday'?'':`<p>${esc(e?.name||'Organización')}</p>`}<div class="activity-bottom">${avatars(ids)}${count?`<span class="activity-count">${count}</span>`:''}<span class="activity-next">${U.icon('arrow')}</span></div>${mine&&myAssignment(t)?'<div class="chips">'+assignChip(myAssignment(t).assignment_status)+'</div>':''}</button><div class="activity-card-actions"><button class="activity-team-link" type="button" data-task-team="${t.id}">${U.icon('chat')} Hablar con el equipo</button>${featureButton(t,t.event_id)}</div></article>`;
}

function noteRow(n){return `<div class="rowCard"><div class="ico">🔔</div><div><b>${esc(n.title)}</b><div class="meta">${esc(n.body||'')}</div><div class="tiny">${new Date(n.created_at).toLocaleString('es-AR')}</div></div>${n.href?`<button class="btn small" data-note-href="${esc(n.href)}">Abrir</button>`:''}</div>`}
function eventCard(e) {
 const cancelled=e.status==='cancelled';
 return `<article class="event-card ${cancelled?'is-cancelled':''}"><div class="event-card-date"><b>${U.date(e.start_date,{day:'numeric'})}</b><span>${U.date(e.start_date,{month:'short'})}</span></div><div class="event-card-info"><span class="tiny">${e.kind==='saturday'?'Sábado':e.kind==='camp'?'Campamento':'Evento TNT'}${cancelled?' · CANCELADO':''}</span><h3>${esc(e.name)}</h3><p>${esc(e.location||fmtDate(e.start_date))}</p>${U.eventTeam(e,S.eventMembers,S.people,S.accounts,eventResponsibleIds(e))}</div><button class="btn icon-only" data-event-open="${e.id}" aria-label="Ver cronograma de ${esc(e.name)}">${U.icon('arrow')}</button></article>`;
}
function workloadFor(pid){const month=today().slice(0,7),ids=new Set();S.assignees.filter(a=>a.person_id===pid&&a.assignment_status!=='declined').forEach(a=>{const t=taskBy(a.task_id),e=t&&eventBy(t.event_id),date=(t?.planned_start||t?.due_at||e?.start_date||'').slice(0,7);if(t&&e&&e.status!=='cancelled'&&!U.completed(t)&&date===month)ids.add(t.id);});return ids.size;}

function viewSchedule(){
 const e=eventBy(S.selectedEvent);if(!e||e.status==='cancelled')return `<div class="page">${empty('Todavía no hay un cronograma','Elegí un sábado para comenzar.','Ver sábados','browse-saturdays')}</div>`;
 const days=eventDays(e.id);if(!days.some(d=>d.id===S.selectedDay))S.selectedDay=days[0]?.id||null;
 const sats=S.events.filter(x=>x.kind==='saturday'&&x.status!=='cancelled').sort((a,b)=>a.start_date.localeCompare(b.start_date)),index=sats.findIndex(x=>x.id===e.id);
 const neighbors=e.kind==='saturday'?`<div class="schedule-jump"><button class="btn" data-schedule-step="-1" ${index<=0?'disabled':''}>${U.icon('back')} Sábado anterior</button><button class="btn" data-schedule-step="1" ${index===sats.length-1?'disabled':''}>Siguiente sábado ${U.icon('arrow')}</button></div>`:'';
 return `<div class="page"><header class="schedule-top"><button class="schedule-back" data-view="saturdays" aria-label="Volver a encuentros">${U.icon('back')}</button><div><span class="eyebrow">CRONOGRAMA</span><h2>${esc(e.name)}</h2><p>${fmtDate(e.start_date)} · ${esc(EVENT_STATUS_LABEL[e.status]||e.status)}</p></div><button class="btn schedule-options" data-schedule-options aria-label="Opciones de ${esc(e.name)}">⋯</button><div class="actions">${canCreateActivity(e.id)?'<button class="btn primary" id="addScheduleItem">'+U.icon('plus')+' Actividad</button>':''}${hasEventProgram(e.id)?'<button class="btn" data-build-schedule>'+U.icon('clock')+' Ver cronograma</button>':''}${eventTasks(e.id).some(t=>activityType(t)==='logistics')?'<button class="btn" data-event-logistics>Logística del evento</button>':''}${canManagePeople(e.id)?'<button class="btn" id="manageEventMembers" data-action="event-members">Personas</button>':''}</div></header>${e.kind==='saturday'?'':`<div class="schedule-day-chooser"><label for="eventSelect">Encuentro</label><select id="eventSelect" class="control" aria-label="Elegir encuentro">${S.events.filter(x=>x.status!=='cancelled').map(x=>`<option value="${x.id}" ${x.id===e.id?'selected':''}>${esc(x.name)} · ${fmtShort(x.start_date)}</option>`).join('')}</select></div><div class="tabs"><button class="tab ${S.cronTab==='schedule'?'on':''}" data-cron="schedule">Cronograma</button><button class="tab ${S.cronTab==='groups'?'on':''}" data-cron="groups">Grupos por día</button></div>`}${neighbors}${scheduleOverview(e)}<section class="schedule-swipe" data-schedule-swipe>${e.kind==='saturday'||S.cronTab==='schedule'?schedulePanel(e,days):groupsPanel(e,days)}</section>${e.kind==='saturday'&&sats.length>1?'<p class="schedule-swipe-hint">Deslizá hacia los costados para cambiar de sábado.</p>':''}</div>`;
}
function scheduleOverview(e){
 const mine=S.tasks.filter(t=>t.event_id===e.id&&taskPeople(t.id).includes(currentPersonId())),coordinators=eventMembers(e.id).filter(m=>m.event_role==='organizer').map(m=>m.person_id),conflicts=canAssignPeople(e.id)?eventConflicts(e.id):[];
 return `<section class="saturday-summary" aria-label="Resumen del encuentro"><div><span class="eyebrow">${e.kind==='saturday'?'ESTE SÁBADO':'ESTE ENCUENTRO'}</span><h3>Nos organizamos juntos</h3>${coordinators.length?`<div class="saturday-coordinators"><span>Coordinan</span>${coordinators.map(pid=>`<button class="personLink" data-person-open="${pid}">${avatarHtml(pid)}<b>${esc(displayName(pid))}</b></button>`).join('')}</div>`:''}</div><div class="saturday-mine"><h3>Lo que te toca</h3>${mine.length?mine.map(t=>`<button class="btn" data-task-open="${t.id}">${t.planned_start?esc(U.time(t.planned_start))+' · ':''}${esc(t.title)} ${U.icon('arrow')}</button>`).join(''):'<p>Podés consultar todas las actividades en el programa.</p>'}</div>${conflicts.length?`<details class="saturday-conflicts"><summary>${conflicts.length} ${conflicts.length===1?'cruce de horario para revisar':'cruces de horario para revisar'}</summary>${conflicts.map(c=>`<p><b>${esc(displayName(c.person_id))}</b>: <button data-task-open="${c.other.id}">${esc(c.other.title)} · ${esc(U.time(c.other.planned_start))}</button> coincide con <button data-task-open="${c.task.id}">${esc(c.task.title)} · ${esc(U.time(c.task.planned_start))}</button>.</p>`).join('')}</details>`:''}</section>`;
}
function schedulePanel(e,days){
 const waiting=pendingProgramTasks(e.id),pending=waiting.length?`<section class="schedule-unscheduled"><div class="sectionHead"><div><h3>${canSeePlanningGaps(e.id)?e.kind==='saturday'?'Actividades sin horario':'Por definir día u horario':'Más actividades'}</h3>${canEditActivity(e.id)?'<p>Abrí una actividad para elegir el día y ubicarla en el programa.</p>':''}</div></div><div class="activities-grid">${waiting.map(t=>taskRow(t,myAssignment(t))).join('')}</div></section>`:'';
 if(e.kind==='saturday'){const d=days[0],items=d?programDayItems(d.id):[];return (items.length?scheduleDayPanel(e,d,true):waiting.length?'':`<div class="schedule-empty"><h3>Este sábado empieza acá.</h3><p>Agregá una actividad; el horario puede quedar para después.</p>${canCreateActivity(e.id)?'<div class="actions"><button class="btn primary" data-add-schedule-activity>Crear primera actividad</button></div>':''}</div>`)+pending;}
 return `<div class="sectionHead"><div><h2>Programa por día</h2>${canSeePlanningGaps(e.id)?'<p class="tiny">Las actividades también se muestran sin horario.</p>':''}</div>${canEditEvent(e.id)?'<button class="btn small" id="editEventDays">Editar evento</button>':''}</div>${days.length?`<div class="tabs">${days.map(d=>`<button class="tab ${d.id===S.selectedDay?'on':''}" data-day="${d.id}">${esc(d.label)}${d.date?' · '+fmtShort(d.date):''}</button>`).join('')}</div>${scheduleDayPanel(e,dayBy(S.selectedDay),false)}`:empty('Todavía no hay programa para este evento','')}${pending}`;
}

function scheduleDayPanel(e,d,isSaturday=false){
 if(!d)return'';const items=programDayItems(d.id),layout=S.programLayouts?.[e.id]||(isSaturday?'time':'type');
 const toolbar=`<div class="program-layout" role="group" aria-label="Orden de las actividades"><button type="button" data-program-layout="time" aria-pressed="${layout==='time'}">Por horario</button><button type="button" data-program-layout="type" aria-pressed="${layout==='type'}">Por tipo</button></div>`;
 const rows=layout==='type'?Object.entries(ACTIVITY_TYPES).map(([type,label])=>{const group=items.filter(i=>activityType(taskBy(i.task_id),i)===type);return group.length?`<section class="program-category" data-program-category="${type}"><header><h3>${label}</h3><span>${group.length}</span></header><div class="timeline">${group.map(i=>scheduleItemRow(e,i)).join('')}</div></section>`:'';}).join(''):`<div class="timeline" data-order-day="${d.id}">${items.map(i=>scheduleItemRow(e,i)).join('')}</div>${canEditActivity(e.id)&&items.length>1?'<p class="schedule-order-hint" role="status" aria-live="polite">Arrastrá desde los seis puntos. Las tarjetas sin horario se mueven libremente; los horarios definidos conservan su orden.</p>':''}`;
 return `${isSaturday?'':`<div class="sectionHead"><h2>${esc(d.label)}</h2>${canCreateActivity(e.id)?'<button class="btn primary small" data-add-schedule-activity>+ Actividad</button>':''}</div>`}${items.length?toolbar+rows:empty('Sin actividades','Agregá una actividad; el horario puede quedar para después.')}`;
}
function scheduleItemRow(e,i){
 const task=taskBy(i.task_id),ids=itemPeople(i.id),mine=ids.includes(currentPersonId()),gaps=canSeePlanningGaps(e.id),count=ids.length?`${ids.length} ${ids.length===1?'responsable':'responsables'}`:gaps?'Sin responsable':'';
 return `<article class="agenda-card ${mine?'is-mine':''} ${task?.is_featured?'is-featured':''} ${!i.starts_at&&!gaps?'agenda-flexible':''}" data-schedule-item="${i.id}" style="${featureStyle(task)}"><div class="agenda-time">${esc(i.starts_at?fmtTime(i.starts_at):gaps?'Sin horario':'')}<small>${i.duration_minutes?i.duration_minutes+' min':''}</small></div><div class="agenda-main"><div class="activity-tags"><span>${esc(ACTIVITY_TYPES[activityType(task,i)])}</span>${featuredBadge(task)}</div><div class="agenda-title"><h3><button class="agenda-title-button" data-item-open="${i.id}" aria-label="Ver ${esc(i.title)}">${esc(i.title)}</button></h3>${mine?'<span class="part-badge">Sos parte</span>':''}</div><p>${esc(i.location||i.description||({game:'Juego',activity:'Actividad',meal:'Merienda / comida',meeting:'Reunión'}[i.item_type]||'Actividad'))}</p>${ids.length||count?`<div class="activity-bottom">${avatars(ids)}${count?`<span class="tiny">${count}</span>`:''}</div>`:''}${task?`<div class="activity-card-actions"><button type="button" class="activity-team-link" data-task-team="${task.id}">${U.icon('chat')} Equipo</button>${featureButton(task,e.id)}</div>`:''}</div></article>`;
}

function groupsPanel(e,days){if(!days.length)return empty('Primero cargá los días','Los equipos se generan por día.');let d=dayBy(S.selectedDay)||days[0];let gs=S.groups.filter(g=>g.event_id===e.id&&g.day_id===d.id).sort((a,b)=>a.sort_order-b.sort_order);let members=eventMembers(e.id).filter(m=>m.include_in_groups!==false);let missing=[];let cfg=S.groupConfigs.find(c=>c.event_id===e.id&&c.day_id===d.id);for(let m of members){let p=pBy(m.person_id);if(!p)continue;if((cfg?.balance_sex??true)&&(!p.sex||p.sex==='U'))missing.push(displayName(p.id)+' · sexo');if((cfg?.balance_age??true)&&!p.birthday)missing.push(displayName(p.id)+' · nacimiento')}
  return `<div class="tabs">${days.map(x=>`<button class="tab ${x.id===d.id?'on':''}" data-day="${x.id}">${esc(x.label)}</button>`).join('')}</div><div class="sectionHead"><div><h2>División · ${esc(d.label)}</h2><div class="tiny">${members.length} personas incluidas</div></div>${canManageEvent(e.id)?'<div class="actions"><button class="btn" data-action="event-members">Participantes</button><button class="btn primary" data-action="group-config">Generar / configurar</button></div>':''}</div>${missing.length?`<div class="warning">Para equilibrar correctamente faltan datos confirmados: ${esc([...new Set(missing)].join(', '))}. La app no infiere sexo por el nombre.</div>`:''}${gs.length?`<div class="groupGrid" style="margin-top:13px">${gs.map(g=>groupBox(g,gs)).join('')}</div>`:empty('Todavía no hay equipos','Configurá Rojo/Azul (o los nombres que quieras) y generá la división.')}`}
function groupBox(g,allGroups){let ms=S.groupMembers.filter(m=>m.group_id===g.id);let avg=ms.length?Math.round(ms.reduce((s,m)=>s+(m.age_snapshot||0),0)/ms.length):0;let sex=ms.reduce((o,m)=>(o[m.sex_snapshot||'U']=(o[m.sex_snapshot||'U']||0)+1,o),{});return `<section class="teamBox"><header class="teamHead"><h3><span class="teamDot" style="background:${esc(g.color)}"></span>${esc(g.name)}</h3><span class="tiny">${ms.length} · edad prom. ${avg||'—'} · F ${sex.F||0} / M ${sex.M||0}</span></header><div class="teamMembers">${ms.map(m=>{let p=pBy(m.person_id);return `<div class="member">${avatarHtml(m.person_id)}<div><b>${esc(displayName(m.person_id))}</b><div class="tiny">${m.age_snapshot??'—'} años · ${m.sex_snapshot==='F'?'F':m.sex_snapshot==='M'?'M':'Sin confirmar'}</div></div>${canManageEvent(g.event_id)?`<select data-move-person="${m.person_id}" data-from-group="${g.id}">${allGroups.map(x=>`<option value="${x.id}" ${x.id===g.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`:''}</div>`}).join('')||'<div class="tiny">Sin personas</div>'}</div></section>`}

function viewSaturdays(){const events=S.events.filter(e=>e.kind==='saturday'&&e.status!=='cancelled'&&e.end_date>=today()).sort((a,b)=>a.start_date.localeCompare(b.start_date)),cancelled=S.events.filter(e=>e.kind==='saturday'&&e.status==='cancelled'&&e.end_date>=today());return `<div class="page"><div class="sectionHead"><div><h2>Sábados</h2><p>Tocá un sábado y abrí su cronograma.</p></div>${TNT.canAction?.('organizacion','create_saturday','*')?'<button class="btn primary" data-action="new-saturday">+ Sábado</button>':''}</div><div class="saturday-list">${events.map(e=>`<button class="saturday-card" data-event-open="${e.id}" aria-label="Abrir cronograma de ${esc(e.name)}"><span class="event-card-date"><b>${U.date(e.start_date,{day:'numeric'})}</b><span>${U.date(e.start_date,{month:'short'})}</span></span><span><small>${esc(EVENT_STATUS_LABEL[e.status]||e.status)}</small><b>${esc(e.name)}</b><small>${eventTasks(e.id).length+eventDays(e.id).reduce((n,d)=>n+dayItems(d.id).filter(i=>!i.task_id).length,0)} actividades · Ver cronograma</small></span>${U.icon('arrow')}</button>`).join('')||empty('Todavía no hay sábados preparados','Creá el próximo sábado y armá su cronograma.')}</div>${cancelled.length?`<details class="saturday-cancelled"><summary>Cancelados (${cancelled.length})</summary><p>Podés abrirlos para revisarlos o reactivarlos.</p><div class="saturday-list">${cancelled.map(eventCard).join('')}</div></details>`:''}</div>`;}
function viewEvents(){const es=S.events.filter(e=>e.kind!=='saturday'&&(S.showPast||e.end_date>=today()));return `<div class="sectionHead"><h2>${S.showPast?'Todos los eventos':'Próximos eventos'}</h2><div class="actions"><button class="btn" data-past>${S.showPast?'Ver próximos':'Ver anteriores'}</button>${(isAdmin()||TNT.canAction?.('organizacion','create_event','*'))?'<button class="btn primary" data-action="new-event">'+U.icon('plus')+' Evento</button>':''}</div></div><div class="grid g2">${es.map(eventCard).join('')||empty('No hay eventos próximos','Elegí una fecha en el calendario para empezar.')}</div>`;}
function viewMyTasks(){return viewActivities();}
function viewTeam(){let q=(window._teamSearch||'').toLowerCase();let ps=staffPeople().filter(p=>displayName(p.id).toLowerCase().includes(q));return `<div class="page"><div class="sectionHead"><div><h2>Equipo TNT</h2><div class="tiny">${ps.length} personas del staff aprobado</div></div><div class="actions"><input class="control" id="teamSearch" placeholder="Buscar" value="${esc(window._teamSearch||'')}">${isAdmin()?'<button class="btn primary" data-action="invite-staff">+ Invitar al staff</button>':''}</div></div><div class="peopleGrid">${ps.map(personCard).join('')}</div></div>`}
function inviteStaffModal(){
 if(!isAdmin())return;
 const people=S.people.filter(p=>p.active!==false&&!p.data_notes?.deleted_at&&aByPid(p.id)?.staff_status!=='approved').sort((a,b)=>a.full_name.localeCompare(b.full_name,'es'));
 modal(`${sheetHead('Invitar al staff','Elegí un perfil existente. Nadie entra al equipo hasta que acepte y complete sus datos.')}<form class="form" id="inviteStaffForm"><div class="field"><label>Buscar perfil</label><input id="inviteSearch" autocomplete="off" placeholder="Nombre o apellido"></div><div class="field"><label>Persona</label><select name="person" required><option value="">Elegí un perfil</option>${people.map(p=>`<option value="${p.id}">${esc(p.full_name)}</option>`).join('')}</select></div><div class="field"><label>Invitar como</label><select name="role">${ROLE_OPTIONS.map(role=>`<option value="${esc(role)}">${esc(role)}</option>`).join('')}</select></div><p>Le llegará el aviso “Te invitaron a ser parte del Staff” a su cuenta TNT. Si aún no se vinculó, lo verá al registrar su perfil.</p><button class="btn primary">Enviar invitación</button><p role="status"></p></form>`);
 const form=$('#inviteStaffForm'),select=form.elements.person;
 $('#inviteSearch').oninput=e=>{const q=e.target.value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es'),previous=select.value;const matches=people.filter(p=>p.full_name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es').includes(q));select.innerHTML='<option value="">Elegí un perfil</option>'+matches.map(p=>`<option value="${p.id}">${esc(p.full_name)}</option>`).join('');select.value=matches.some(p=>p.id===previous)?previous:'';U.enhanceSelects(form);};
 form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button[type=submit],button:not([type])');button.disabled=true;const r=await sb.rpc('tnt_invite_staff',{p_person:select.value,p_role:form.elements.role.value});if(r.error){form.querySelector('[role=status]').textContent=r.error.message;button.disabled=false;return;}await closeModal();toast('Invitación enviada');};
}
function personCard(p){const a=aByPid(p.id),tasks=S.assignees.filter(x=>x.person_id===p.id&&S.tasks.some(t=>t.id===x.task_id&&!U.completed(t))).length,av=S.availability.find(x=>x.person_id===p.id&&x.date===today());return `<article class="person-card"><div class="person-card-top">${U.avatar(p,a||{},'large')}<span class="tnt-pill">${av?.status==='unavailable'?'No disponible hoy':av?.status==='available'?'Disponible hoy':'Equipo TNT'}</span></div><h3>${esc(displayName(p.id))}</h3><p>${esc(a?.ministry_role||'Participante')}</p><div class="person-areas">${(a?.service_areas||[]).slice(0,3).map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="person-foot"><span>${tasks} ${tasks===1?'tarea activa':'tareas activas'}</span><button class="btn" data-person-open="${p.id}">Ver perfil ${U.icon('arrow')}</button></div></article>`;}
function viewTemplates(){return `<div class="page"><section class="hero"><div class="eyebrow">Reutilizable</div><h1>Plantillas</h1><p>Creá tipos de actividades y sugerencias editables. Ninguna plantilla agrega tareas por sí sola.</p></section><div class="sectionHead"><h2>Plantillas</h2>${canManageTemplates()?'<button class="btn primary" data-action="new-template">+ Plantilla</button>':''}</div><div class="grid g2">${S.templates.map(t=>templateCard(t)).join('')}</div></div>`}
function templateCard(t){let items=S.templateItems.filter(i=>i.template_id===t.id).sort((a,b)=>a.sort_order-b.sort_order);return `<article class="card"><div class="quick"><div class="ico">${t.kind==='saturday'?'🗓':'▦'}</div><div class="grow"><h3>${esc(t.name)}</h3><p>${esc(t.description||'')}</p></div></div><div class="chips">${items.map(i=>`<span class="chip">${esc(i.icon||'✓')} ${esc(i.title)}</span>`).join('')}</div>${canManageTemplates()?`<div class="actions" style="margin-top:13px"><button class="btn small" data-template-edit="${t.id}">Editar</button><button class="btn small primary" data-template-start="${t.id}">Usar</button></div>`:''}</article>`}
function viewAdmin(){if(!isAdmin())return `<div class="page">${empty('Solo Admin','No tenés permiso para esta sección.')}</div>`;let accounts=S.accounts.map(a=>({a,p:pBy(a.person_id)})).filter(x=>x.p);return `<div class="page"><section class="hero"><div class="eyebrow">Sistema</div><h1>Administración</h1><p>Gestioná roles TNT, administradores, acceso a módulos y cuentas habilitadas.</p></section><div class="sectionHead"><h2>Usuarios</h2><div class="actions"><button class="btn" data-action="general-notification">Notificación general</button><button class="btn primary" data-action="invite-staff">+ Invitar perfil existente</button></div></div><div class="list">${accounts.map(({a,p})=>adminUserRow(a,p)).join('')}</div></div>`}
function adminUserRow(a,p){return `<div class="rowCard">${avatarHtml(p.id)}<div><b>${esc(a.nickname||p.full_name)}</b><div class="meta">${esc(a.email||'Sin email')} · ${a.auth_user_id?'Cuenta vinculada':'Pendiente de ingreso'}</div><div class="chips"><span class="chip">${esc(a.ministry_role)}</span>${a.system_role==='admin'?'<span class="chip">Admin</span>':''}${!a.enabled?'<span class="status declined">Deshabilitado</span>':''}</div></div><div class="actions"><button class="btn small" data-admin-user="${p.id}">Gestionar</button></div></div>`}


/* organizacion/org3a.js */
function bindViewSpecific(){
  if(S.view==='schedule')bindSchedule();if(S.view==='saturdays')bindSaturdays();if(S.view==='team'){let x=$('#teamSearch');if(x)x.oninput=e=>{window._teamSearch=e.target.value;render()}}if(S.view==='templates'){$$('[data-template-edit]').forEach(b=>b.onclick=()=>templateModal(b.dataset.templateEdit));$$('[data-template-start]').forEach(b=>b.onclick=()=>{const t=S.templates.find(x=>x.id===b.dataset.templateStart);if(t?.kind==='saturday')saturdayCreateModal();else eventCreateModal(b.dataset.templateStart)})}if(S.view==='admin')$$('[data-admin-user]').forEach(b=>b.onclick=()=>adminUserModal(b.dataset.adminUser));
  $$('[data-note-href]').forEach(b=>b.onclick=()=>openInternal(b.dataset.noteHref));
}


function bindSchedule(){
  $$('[data-program-layout]').forEach(b=>b.onclick=()=>{S.programLayouts??={};S.programLayouts[S.selectedEvent]=b.dataset.programLayout;render();});
  $$('[data-event-logistics]').forEach(b=>b.onclick=()=>{eventDetailModal(S.selectedEvent);$('#event-logistics')?.scrollIntoView?.({block:'start'});});
  $('#eventSelect')?.addEventListener('change',e=>{S.selectedEvent=e.target.value;S.selectedDay=eventDays(S.selectedEvent)[0]?.id||null;render()});
  $$('[data-cron]').forEach(b=>b.onclick=()=>{S.cronTab=b.dataset.cron;render()});$$('[data-day]').forEach(b=>b.onclick=()=>{S.selectedDay=b.dataset.day;render()});
  $('#addScheduleItem')?.addEventListener('click',()=>activityChooserModal(S.selectedEvent));$('#editEventDays')?.addEventListener('click',()=>editEvent(S.selectedEvent));
  $$('[data-item-open]').forEach(b=>b.onclick=()=>scheduleItemDetailModal(b.dataset.itemOpen));
  $$('[data-run-next]').forEach(b=>b.onclick=()=>cycleRunStatus(b.dataset.runNext));
  $$('[data-schedule-options]').forEach(b=>b.onclick=()=>scheduleOptions(S.selectedEvent));$$('[data-build-schedule]').forEach(b=>b.onclick=()=>quickScheduleModal(S.selectedEvent));$$('[data-add-schedule-activity]').forEach(b=>b.onclick=()=>activityChooserModal(S.selectedEvent));$$('[data-schedule-step]').forEach(b=>b.onclick=()=>stepSaturday(Number(b.dataset.scheduleStep)));bindScheduleSwipe();
  $$('[data-move-person]').forEach(s=>s.onchange=()=>moveGroupMember(s.dataset.movePerson,s.dataset.fromGroup,s.value));
}
function bindSaturdays(){
  $('#satPrev')?.addEventListener('click',()=>{S.satMonth=new Date(S.satMonth.getFullYear(),S.satMonth.getMonth()-1,1);render()});$('#satNext')?.addEventListener('click',()=>{S.satMonth=new Date(S.satMonth.getFullYear(),S.satMonth.getMonth()+1,1);render()});
  $$('[data-create-sat]').forEach(b=>b.onclick=()=>createSaturday(b.dataset.createSat));
}

async function createSaturday(date){let {data,error}=await sb.rpc('tnt_create_saturday',{p_date:date,p_name:'Sábado TNT'});if(error)return toast(errMsg(error));await loadAll();toast('Sábado preparado');openSchedule(data)}
function saturdayCreateModal(){modal(`${sheetHead('Preparar sábado','Sin tareas predefinidas: las agregás y asignás después.')}<form class="form" id="satForm"><div class="field"><label>Fecha</label><input type="date" name="date" min="${today()}" value="${esc(S.calendarDate&&S.calendarDate>=today()?S.calendarDate:'')}" required></div><div class="field"><label>Nombre</label><input name="name" value="Sábado TNT"></div><p>Primero se crea el sábado vacío. Después elegís sugerencias o redactás las tareas, y asignás responsables.</p><button class="btn primary">Crear sábado sin tareas</button></form>`);$('#satForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),{data,error}=await sb.rpc('tnt_create_saturday',{p_date:f.get('date'),p_name:f.get('name')});if(error)return toast(errMsg(error));await closeModal();await loadAll();toast('Sábado creado');openSchedule(data)}}
function eventCreateModal(templateId=''){
 const templates=S.templates.filter(t=>t.kind!=='saturday');const chosen=templates.find(t=>t.id===templateId);
 if(!(isAdmin()||TNT.canAction?.('organizacion','create_event','*')))return toast('No tenés permiso para crear eventos.');
 modal(`${sheetHead('Crear evento','Definí lo esencial. Después armás el programa desde el evento.')}<form class="form" id="eventForm"><div class="field"><label>Tipo de actividad</label><select name="template"><option value="">Evento sin plantilla</option>${templates.map(t=>`<option value="${t.id}" ${chosen?.id===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select><small>La plantilla solo define el tipo de encuentro; no agrega tareas automáticamente.</small></div><div class="field"><label>Nombre</label><input name="name" required placeholder="Congreso TNT"></div><div class="formRow"><div class="field"><label>Desde</label><input type="date" name="start" value="${esc(S.calendarDate||'')}" min="${today()}" required></div><div class="field"><label>Hasta</label><input type="date" name="end"></div></div><div class="field"><label>Lugar</label><input name="location"></div><div class="event-create-note"><b>Vos quedás como coordinador/a inicial</b><span>Después podés sumar más coordinadores y participantes desde Personas.</span></div><button class="btn primary" type="submit">Crear evento</button></form>`);
 const form=$('#eventForm');
 form.onsubmit=async ev=>{ev.preventDefault();const btn=ev.target.querySelector('[type=submit]'),fd=new FormData(form),tpl=templates.find(t=>t.id===fd.get('template')),start=String(fd.get('start')),end=String(fd.get('end')||start);if(end<start)return toast('La fecha de cierre no puede ser anterior al inicio.');btn.disabled=true;const payload={name:String(fd.get('name')).trim(),kind:tpl?.kind||'event',activity_type_id:tpl?.id||null,start_date:start,end_date:end,location:fd.get('location')||null};const {data,error}=await sb.rpc('tnt_create_event',{p_values:payload});if(error){btn.disabled=false;return toast(errMsg(error));}closeModal();await loadAll();render();toast('Evento creado');eventDetailModal(data)};
}

function eventDetailModal(id){
 let e=eventBy(id);if(!e)return;
 let tasks=eventTasks(id).filter(t=>activityType(t)!=='logistics'),logistics=eventTasks(id).filter(t=>activityType(t)==='logistics'),members=eventMembers(id),orgs=members.filter(m=>m.event_role==='organizer'),manager=canManageEvent(id),canPeople=canManagePeople(id),canCreate=canCreateActivity(id);
 const statusClass='event-status-'+e.status;
 modal(`${sheetHead(e.name,`${fmtDate(e.start_date)}${e.end_date!==e.start_date?' → '+fmtDate(e.end_date):''}`)}
   <section class="event-overview">
     <div class="event-status-card ${statusClass}"><span>Estado</span><strong>${esc(EVENT_STATUS_LABEL[e.status]||e.status)}</strong>${e.status==='cancelled'?'<small>El sábado sigue guardado; podés reactivarlo editando el estado.</small>':''}</div>
     <div class="event-people-card"><span>Coordina</span><div class="event-organizers">${orgs.length?orgs.map(m=>`<button class="personLink" data-person-open="${m.person_id}">${avatarHtml(m.person_id)}<span>${esc(displayName(m.person_id))}</span></button>`).join(''):'<small>Sin coordinadores</small>'}</div></div>
     <div class="event-people-card"><span>Equipo</span><strong>${members.length}</strong><small>${members.length===1?'persona incluida':'personas incluidas'}</small></div>
   </section>
   <div class="sectionHead event-task-head"><div><span class="eyebrow">ACTIVIDADES</span><h2>${tasks.length?tasks.length+' cargadas':'Todavía no hay actividades'}</h2></div>${canPeople||canCreate?`<div class="actions">${canPeople?'<button class="btn" id="manageEventMembers">Personas</button>':''}${canCreate?'<button class="btn primary" id="chooseTask">+ Elegir actividad</button>':''}</div>`:''}</div>
   ${tasks.length?`<div class="list">${tasks.map(t=>taskRow(t,myAssignment(t))).join('')}</div>`:`<div class="event-empty"><div class="event-empty-icon">＋</div><h3>${e.kind==='saturday'?'Armá este sábado desde acá':'Armá este encuentro desde acá'}</h3><p>Agregá bienvenida, juegos, palabra, merienda o cualquier actividad. ${e.kind==='saturday'?'La fecha ya está tomada del sábado.':'El cronograma se va armando a medida que agregás actividades.'}</p>${canCreate?'<button class="btn primary" id="newTaskEmpty">Agregar primera actividad</button>':''}</div>`}
   ${logistics.length||canCreate?`<section class="event-logistics" id="event-logistics"><div class="sectionHead"><div><span class="eyebrow">ORGANIZACIÓN DEL EVENTO</span><h2>Logística del evento</h2><p>Áreas de trabajo, preparativos y cosas para llevar.</p></div>${canCreate?'<button class="btn" id="newLogistics">+ Área de logística</button>':''}</div>${logistics.length?`<div class="list">${Object.entries(LOGISTICS_PHASES).map(([phase,label])=>{const rows=logistics.filter(t=>(t.logistics_phase||'before')===phase);return rows.length?'<section class="logistics-phase" data-logistics-phase="'+phase+'"><h3>'+label+'</h3>'+rows.map(t=>taskRow(t,myAssignment(t))).join('')+'</section>':'';}).join('')}</div>`:'<p class="tiny">Todavía no hay áreas de logística.</p>'}</section>`:''}
 `,true);
 $$('[data-task-open]').forEach(b=>b.onclick=()=>taskDetailModal(b.dataset.taskOpen));
 $$('[data-person-open]').forEach(b=>b.onclick=()=>personResponsibilitiesModal(b.dataset.personOpen));
 $('#manageEventMembers')?.addEventListener('click',()=>eventMembersModal(id));
 $('#chooseTask')?.addEventListener('click',()=>activityChooserModal(id));
 $('#newTaskEmpty')?.addEventListener('click',()=>activityChooserModal(id));
 $('#newLogistics')?.addEventListener('click',()=>taskEditModal(null,id,null,{task_type:'logistics'}));
 bindActivityActions($('#modal'));
}

function dayModal(d=null){let e=eventBy(S.selectedEvent),days=eventDays(e.id);modal(`${sheetHead(d?'Editar día':'Agregar día')}<form class="form" id="dayForm"><div class="field"><label>Nombre</label><input name="label" value="${esc(d?.label||`Día ${days.length+1}`)}" placeholder="Día 1 / Viernes" required></div><div class="field"><label>Fecha</label><input type="date" name="date" value="${esc(d?.date||'')}"></div><button class="btn primary">Guardar</button></form>`);$('#dayForm').onsubmit=async ev=>{ev.preventDefault();let f=new FormData(ev.target),payload={event_id:e.id,label:f.get('label'),date:f.get('date')||null,sort_order:d?.sort_order??days.length};let q=d?sb.from('tnt_schedule_days').update(payload).eq('id',d.id):sb.from('tnt_schedule_days').insert(payload).select().single();let {data,error}=await q;if(error)return toast(errMsg(error));closeModal();await loadAll();S.selectedDay=d?.id||data?.id;render()}}


/* organizacion/org3b.js */
function scheduleItemModal(item=null){let d=dayBy(item?.day_id||S.selectedDay),e=eventBy(d?.event_id);if(!d||!e)return;const presentation=taskBy(item?.task_id);let selected=item?itemPeople(item.id):[];let pool=[...new Set([...staffPeople().map(p=>p.id),...selected])];modal(`${sheetHead(item?'Editar actividad':'Nueva actividad',e.kind==='saturday'?'':d.label)}<form class="form" id="itemForm"><div class="formRow"><div class="field"><label>Nombre</label><input name="title" value="${esc(item?.title||'')}" required></div><div class="field" data-program-extra><label>Tipo</label><select name="type">${Object.entries(ITEM_TYPE_LABEL).map(([value,label])=>`<option value="${value}" ${(item?.item_type||'activity')===value?'selected':''}>${label}</option>`).join('')}</select></div></div><div class="formRow three"><div class="field"><label>Hora</label><input type="time" name="time" value="${esc(item?.starts_at?.slice(0,5)||'')}"></div><div class="field"><label>Duración (min)</label><input type="number" name="duration" min="0" value="${esc(item?.duration_minutes||'')}"></div><div class="field" data-program-extra><label>Lugar</label><input name="location" value="${esc(item?.location||'')}"></div></div><div class="field" data-program-extra><label>Descripción / instrucciones</label><textarea name="description">${esc(item?.description||'')}</textarea></div><div class="field" data-program-extra><label>Video explicativo (YouTube)</label><input name="video" value="${esc(item?.video_url||'')}" placeholder="https://youtube.com/..."></div><div class="field" data-program-extra><label>Materiales</label><textarea name="materials">${esc(item?.materials||'')}</textarea></div><label class="checkRow"><input id="program-advanced" type="checkbox" ${item?.description||item?.video_url||item?.materials||item?.location?'checked':''}> Añadir instrucciones, enlace o materiales</label><div class="field"><label>Responsables de la actividad</label><div class="checkList">${pool.map(id=>`<label class="checkRow responsible-picker"><input type="checkbox" name="person" value="${id}" ${selected.includes(id)?'checked':''}>${avatarHtml(id)}<span>${esc(displayName(id))}</span><small>${esc(aByPid(id)?.ministry_role||'')}</small></label>`).join('')}</div></div>${featureFields(presentation)}<button class="btn primary">Guardar</button></form>`);bindFeatureFields($('#itemForm'));const advanced=$('#program-advanced');function toggleExtra(){$$('[data-program-extra]').forEach(el=>el.hidden=!advanced.checked)}advanced.onchange=toggleExtra;toggleExtra();$('#itemForm').onsubmit=async ev=>{ev.preventDefault();let f=new FormData(ev.target),payload={day_id:d.id,title:f.get('title'),item_type:f.get('type'),starts_at:f.get('time')||null,duration_minutes:Number(f.get('duration'))||null,location:f.get('location')||null,description:f.get('description')||null,video_url:f.get('video')||null,materials:f.get("materials")||null,sort_order:item?.sort_order??dayItems(d.id).length,is_featured:f.has('is_featured'),feature_color:f.get('feature_color')||'lime'};const r=await sb.rpc('tnt_save_schedule_item',{p_id:item?.id||null,p_day:d.id,p_values:payload,p_people:f.getAll('person')});if(r.error)return toast(errMsg(r.error));closeModal();await loadAll();render()}}
function youtubeEmbed(url){try{let u=new URL(url),id=u.hostname.includes('youtu.be')?u.pathname.slice(1):u.searchParams.get('v');return id?`<iframe style="width:100%;aspect-ratio:16/9;border:0;border-radius:16px" src="https://www.youtube.com/embed/${encodeURIComponent(id)}" allowfullscreen></iframe>`:''}catch{return''}}
function scheduleItemDetailModal(id){let i=S.items.find(x=>x.id===id),d=dayBy(i?.day_id),e=eventBy(d?.event_id);if(!i||!e)return;if(i.task_id&&taskBy(i.task_id))return taskDetailModal(i.task_id);let rp=itemPeople(i.id),subtitle=`${e.kind==='saturday'?'':d.label+' · '}${fmtTime(i.starts_at)}${i.duration_minutes?' · '+i.duration_minutes+' min':''}`;modal(`${sheetHead(i.title,subtitle)}${i.video_url?youtubeEmbed(i.video_url):''}<div class="grid g2" style="margin-top:13px"><div class="card"><h3>Responsables</h3><div class="responsibles">${rp.map(pid=>`<button class="personLink" data-person-open="${pid}">${avatarHtml(pid)} ${esc(displayName(pid))}</button>`).join('')||(canSeePlanningGaps(e.id)?'<span class="tiny">Sin asignar</span>':'')}</div></div></div><div class="card" style="margin-top:12px"><h3>Instrucciones</h3><p>${esc(i.description||'Sin descripción')}</p>${i.materials?`<h3 style="margin-top:14px">Materiales</h3><p>${esc(i.materials)}</p>`:''}${i.location?`<p><b>Lugar:</b> ${esc(i.location)}</p>`:''}</div>${canManageEvent(e.id)?`<div class="actions" style="margin-top:13px"><button class="btn" id="editItem">Editar</button><button class="btn danger" id="deleteItem">Eliminar</button></div>`:''}`);$$('[data-person-open]').forEach(b=>b.onclick=()=>personResponsibilitiesModal(b.dataset.personOpen));$('#editItem')?.addEventListener('click',()=>scheduleItemModal(i));$('#deleteItem')?.addEventListener('click',async()=>{if(i.task_id)return archiveActivities([i.task_id]);const r=await sb.rpc('tnt_archive_schedule_item',{p_item:i.id,p_restore:false});if(r.error)return toast(r.error.message);await closeModal();await loadAll();render();TNTExperience.undo('Actividad eliminada',async()=>{const result=await sb.rpc('tnt_archive_schedule_item',{p_item:i.id,p_restore:true});if(result.error)throw result.error;await loadAll();render();});})}
async function cycleRunStatus(id){let i=S.items.find(x=>x.id===id),next=i.run_status==='pending'?'live':i.run_status==='live'?'done':'pending';let {error}=await sb.from('tnt_schedule_items').update({run_status:next}).eq('id',id);if(error)return toast(errMsg(error));await loadAll();render()}

function eventMembersModal(eventId){
 const e=eventBy(eventId),current=eventMembers(eventId),map=new Map(current.map(m=>[m.person_id,m]));
 const organizers=current.filter(m=>m.event_role==='organizer'),lockSelf=organizers.length===1&&organizers[0]?.person_id===currentPersonId()&&!isAdmin()&&!TNT.canAction?.('organizacion','manage_people','*');
 const showGroups=e.kind!=='saturday';
 modal(`${sheetHead(e.kind==='saturday'?'Personas del sábado':'Personas del evento',e.kind==='saturday'?'Elegí quién forma parte y quién coordina. Puede haber más de un coordinador.':'Elegí participantes y coordinadores.')}`
   +`<form class="form member-manager" id="membersForm">
      <div class="member-role-guide"><b>Cómo funciona</b><span>Primero incluís a la persona. Después elegís si <strong>participa</strong> o <strong>coordina</strong>. Si no está incluida, su función no se guarda.</span></div>
      <div class="checkList">${staffPeople().map(p=>{const m=map.get(p.id),locked=lockSelf&&p.id===currentPersonId(),label=esc(displayName(p.id)),included=!!m||locked,role=(locked?'organizer':m?.event_role)||'participant';return `
        <article class="member-card ${included?'is-included':''}" data-member-row="${p.id}">
          <label class="member-main">
            <input type="checkbox" name="person" value="${p.id}" ${included?'checked':''} ${locked?'disabled':''} aria-label="Incluir a ${label}">
            ${avatarHtml(p.id)}
            <span><b>${label}</b><small>${esc(aByPid(p.id)?.ministry_role||'Equipo TNT')}</small></span>
          </label>
          <div class="member-role-choice" role="group" aria-label="Función de ${label}">
            <label><input type="radio" name="role_${p.id}" value="participant" ${role==='participant'?'checked':''} ${included&&!locked?'':'disabled'}><span>Participa</span></label>
            <label><input type="radio" name="role_${p.id}" value="organizer" ${role==='organizer'?'checked':''} ${included&&!locked?'':'disabled'}><span>Coordina</span></label>
          </div>
          ${showGroups?`<label class="member-groups"><input type="checkbox" name="games_${p.id}" ${m?.include_in_groups!==false?'checked':''} ${included?'':'disabled'}> Incluir en grupos</label>`:''}
        </article>`}).join('')}</div>
      <button class="btn primary member-save" type="submit">Guardar personas</button>
    </form>`,true);
 const form=$('#membersForm');
 const syncRow=row=>{
   const check=row.querySelector('input[name="person"]'),enabled=check.checked;
   row.classList.toggle('is-included',enabled);
   row.querySelectorAll('.member-role-choice input').forEach(x=>{if(!x.closest('article').querySelector('input[name="person"]').disabled)x.disabled=!enabled;});
   const groups=row.querySelector('.member-groups input');if(groups)groups.disabled=!enabled;
 };
 form.querySelectorAll('[data-member-row]').forEach(row=>{syncRow(row);const c=row.querySelector('input[name="person"]');c.addEventListener('change',()=>syncRow(row));});
 form.onsubmit=async ev=>{
   ev.preventDefault();
   const submit=ev.target.querySelector('[type=submit]');submit.disabled=true;
   const fd=new FormData(ev.target),ids=fd.getAll('person');if(lockSelf&&!ids.includes(currentPersonId()))ids.push(currentPersonId());
   const rows=ids.map(person_id=>({event_id:eventId,person_id,event_role:(lockSelf&&person_id===currentPersonId())?'organizer':(fd.get('role_'+person_id)||'participant'),include_in_groups:showGroups?fd.get('games_'+person_id)==='on':false}));
   try{
     const r=await sb.rpc('tnt_save_event_members',{p_event:eventId,p_members:rows});if(r.error)throw r.error;
     clearOrgModal();await loadAll();render();toast('Personas actualizadas');
   }catch(error){toast(errMsg(error));submit.disabled=false;}
 };
}


/* organizacion/org4a.js */
function groupConfigModal(dayId){let d=dayBy(dayId),e=eventBy(d?.event_id);if(!d||!e)return;let cfg=S.groupConfigs.find(c=>c.event_id===e.id&&c.day_id===d.id),existing=S.groups.filter(g=>g.event_id===e.id&&g.day_id===d.id).sort((a,b)=>a.sort_order-b.sort_order),count=cfg?.group_count||Math.max(2,existing.length||2),names=existing.length?existing.map(g=>g.name).join('\n'):['Rojo','Azul'].join('\n'),colors=existing.length?existing.map(g=>g.color).join('\n'):['#e5484d','#3b82f6'].join('\n');modal(`${sheetHead('Configurar grupos',d.label)}<form class="form" id="groupForm"><div class="field"><label>Cantidad de equipos</label><input type="number" name="count" min="2" max="8" value="${count}"></div><div class="formRow"><div class="field"><label>Nombres (uno por línea)</label><textarea name="names">${esc(names)}</textarea></div><div class="field"><label>Colores HEX (uno por línea)</label><textarea name="colors">${esc(colors)}</textarea></div></div><label class="checkRow"><input type="checkbox" name="age" ${cfg?.balance_age===false?'':'checked'}><span>Equilibrar edades</span></label><label class="checkRow"><input type="checkbox" name="sex" ${cfg?.balance_sex===false?'':'checked'}><span>Equilibrar sexo confirmado</span></label><label class="checkRow"><input type="checkbox" name="rotate" ${cfg?.avoid_previous_day===false?'':'checked'}><span>Evitar repetir equipo del día anterior</span></label><div class="warning">La app nunca infiere sexo por el nombre. Si falta sexo o fecha de nacimiento, te lo va a pedir antes de generar.</div><button class="btn primary">Generar equipos</button></form>`);$('#groupForm').onsubmit=e2=>generateGroups(e2,e,d,cfg)}
async function generateGroups(ev,e,d,cfg){ev.preventDefault();let f=new FormData(ev.target),count=Math.max(2,Math.min(8,Number(f.get('count'))||2)),names=String(f.get('names')||'').split(/\n+/).map(s=>s.trim()).filter(Boolean),colors=String(f.get('colors')||'').split(/\n+/).map(s=>s.trim()).filter(Boolean),balanceAge=f.get('age')==='on',balanceSex=f.get('sex')==='on',rotate=f.get('rotate')==='on';while(names.length<count)names.push(`Equipo ${names.length+1}`);while(colors.length<count)colors.push(['#e5484d','#3b82f6','#8b5cf6','#10b981','#f59e0b','#ec4899'][colors.length%6]);let pool=eventMembers(e.id).filter(m=>m.include_in_groups!==false).map(m=>pBy(m.person_id)).filter(Boolean);let missing=[];pool.forEach(p=>{if(balanceSex&&(!p.sex||p.sex==='U'))missing.push(displayName(p.id)+' (sexo)');if(balanceAge&&!p.birthday)missing.push(displayName(p.id)+' (nacimiento)')});if(missing.length)return toast('Faltan datos: '+missing.slice(0,4).join(', ')+(missing.length>4?'…':''));
  let payload={event_id:e.id,day_id:d.id,group_count:count,balance_age:balanceAge,balance_sex:balanceSex,avoid_previous_day:rotate,updated_by:currentPersonId()};let qr=cfg?await sb.from('tnt_group_configs').update(payload).eq('id',cfg.id):await sb.from('tnt_group_configs').insert(payload);if(qr.error)return toast(errMsg(qr.error));
  let old=S.groups.filter(g=>g.event_id===e.id&&g.day_id===d.id);if(old.length){let del=await sb.from('tnt_groups').delete().in('id',old.map(g=>g.id));if(del.error)return toast(errMsg(del.error))}
  let {data:newGroups,error:ge}=await sb.from('tnt_groups').insert([...Array(count)].map((_,i)=>({event_id:e.id,day_id:d.id,name:names[i],color:colors[i],sort_order:i}))).select();if(ge)return toast(errMsg(ge));newGroups.sort((a,b)=>a.sort_order-b.sort_order);
  let days=eventDays(e.id),idx=days.findIndex(x=>x.id===d.id),prev=idx>0?days[idx-1]:null,prevMap=new Map();if(prev){let pgs=S.groups.filter(g=>g.event_id===e.id&&g.day_id===prev.id);for(let g of pgs)for(let m of S.groupMembers.filter(x=>x.group_id===g.id))prevMap.set(m.person_id,g.name)}
  let persons=pool.map(p=>({p,age:age(p.birthday,d.date?new Date(d.date+'T12:00:00'):new Date()),sex:p.sex||'U'}));persons.sort((a,b)=>(a.sex||'').localeCompare(b.sex||'')||((b.age||0)-(a.age||0)));let teams=newGroups.map(g=>({g,people:[],ageSum:0,sex:{F:0,M:0,U:0}}));let targetAvg=persons.length?persons.reduce((s,x)=>s+(x.age||0),0)/persons.length:0;
  for(let x of persons){let scored=teams.map(t=>{let size=t.people.length,score=size*100;if(balanceSex)score+=(t.sex[x.sex]||0)*35;if(balanceAge&&x.age!=null){let avg=(t.ageSum+x.age)/(size+1);score+=Math.abs(avg-targetAvg)*4}if(rotate&&prevMap.get(x.p.id)===t.g.name)score+=75;return{t,score}}).sort((a,b)=>a.score-b.score);let t=scored[0].t;t.people.push(x);t.ageSum+=x.age||0;t.sex[x.sex]=(t.sex[x.sex]||0)+1}
  let rows=[];teams.forEach(t=>t.people.forEach(x=>rows.push({group_id:t.g.id,person_id:x.p.id,age_snapshot:x.age,sex_snapshot:x.sex})));if(rows.length){let ir=await sb.from('tnt_group_members').insert(rows);if(ir.error)return toast(errMsg(ir.error))}closeModal();await loadAll();render();toast('Equipos generados')}
async function moveGroupMember(personId,fromId,toId){if(fromId===toId)return;let old=S.groupMembers.find(m=>m.group_id===fromId&&m.person_id===personId);let d=await sb.from('tnt_group_members').delete().eq('group_id',fromId).eq('person_id',personId);if(d.error)return toast(errMsg(d.error));let i=await sb.from('tnt_group_members').insert({group_id:toId,person_id:personId,age_snapshot:old?.age_snapshot,sex_snapshot:old?.sex_snapshot});if(i.error)return toast(errMsg(i.error));await loadAll();render()}



