function projectEvent(id){const e=eventBy(id);if(!e)return;const d=document.createElement('dialog');d.className='org-projection';document.body.append(d);const paint=()=>{d.innerHTML=`<header><div><span class="eyebrow">TNT · MODO PANTALLA</span><h1>${esc(e.name)}</h1><p>${esc(e.location||'')} · ${fmtDate(e.start_date)}</p></div><button class="btn" id="projection-close">Cerrar</button></header>${eventDays(id).map(day=>`<h2>${esc(day.label)} · ${fmtShort(day.date)}</h2><div class="projection-list">${programDayItems(day.id).map(i=>`<article class="${i.run_status==='live'?'is-live':''} ${taskBy(i.task_id)?.is_featured?'is-featured':''}" style="${featureStyle(taskBy(i.task_id))}"><b class="${i.starts_at?'':'is-untimed'}">${i.starts_at?fmtTime(i.starts_at):canSeePlanningGaps(id)?'Sin horario':''}</b><div><h3>${esc(i.title)}</h3><p>${itemPeople(i.id).map(pid=>esc(displayName(pid))).join(' · ')||(canSeePlanningGaps(id)?'Sin responsables asignados':'')}</p></div><span>${RUN_LABEL[i.run_status||'pending']}</span></article>`).join('')}</div>`).join('')}${pendingProgramTasks(id).length?'<h2>'+(canSeePlanningGaps(id)?'Por definir día u horario':'Más actividades')+'</h2><div class="projection-list">'+pendingProgramTasks(id).map(t=>'<article class="'+(t.is_featured?'is-featured':'')+'" style="'+featureStyle(t)+'"><b class="'+(t.planned_start?'':'is-untimed')+'">'+esc(t.planned_start?U.time(t.planned_start):canSeePlanningGaps(id)?'Sin horario':'')+'</b><div><h3>'+esc(t.title)+'</h3><p>'+taskPeople(t.id).map(pid=>esc(displayName(pid))).join(' · ')+'</p></div><span>'+esc(STATUS_LABEL[t.status]||'Pendiente')+'</span></article>').join('')+'</div>':''}${!hasEventProgram(id)?'<p>Todavía no hay actividades.</p>':''}`;d.querySelector('#projection-close').onclick=()=>d.close();};paint();d.showModal();const timer=setInterval(async()=>{if(document.hidden)return;const days=eventDays(id).map(x=>x.id);if(!days.length)return;const r=await sb.from('tnt_schedule_items').select('*').in('day_id',days);if(!r.error){S.items=S.items.filter(i=>!days.includes(i.day_id)).concat((r.data||[]).filter(i=>!i.archived_at));paint();}},10000);d.addEventListener('close',()=>{clearInterval(timer);d.remove();});}
function replacementCandidates(taskId){const target=taskBy(taskId),active=new Set(taskPeople(taskId)),day=target.planned_start?U.dateKey(target.planned_start):eventBy(target.event_id)?.start_date;const overlap=(a,b)=>{if(!a.planned_start||!b.planned_start)return false;const as=Date.parse(a.planned_start),bs=Date.parse(b.planned_start);return as<bs+(b.duration_minutes||60)*60000&&bs<as+(a.duration_minutes||60)*60000;};const rows=staffPeople().filter(p=>!active.has(p.id)).map(p=>{const tasks=S.tasks.filter(t=>taskPeople(t.id).includes(p.id)&&!U.completed(t.status)),av=S.availability.find(a=>a.person_id===p.id&&a.date===day),unavailable=av?.status==='unavailable',conflict=tasks.some(t=>t.id!==taskId&&overlap(t,target));return{p,load:tasks.length,unavailable,conflict,known:!!av,score:(unavailable?1000:0)+(conflict?500:0)+tasks.length};}).sort((a,b)=>a.score-b.score);const o=U.modal('Buscar reemplazo',`<p>Ordenados por disponibilidad registrada y tareas activas. Revisá la propuesta antes de asignar.</p>${rows.slice(0,20).map(x=>`<div class="chat-participant replacement-row">${avatarHtml(x.p.id)}<div><b>${esc(displayName(x.p.id))}</b><small>${x.unavailable?'No disponible':x.conflict?'Coincide con otra tarea':x.load+' tareas activas'}${!x.known?' · Disponibilidad sin confirmar':''}</small></div><button class="btn" data-candidate="${x.p.id}">Asignar</button></div>`).join('')||'<p>No hay más personas disponibles en el equipo.</p>'}`);o.querySelectorAll('[data-candidate]').forEach(b=>b.onclick=async()=>{const x=rows.find(x=>x.p.id===b.dataset.candidate);if((x.unavailable||x.conflict)&&!await U.confirm('Hay una dificultad de disponibilidad. ¿Querés asignar igual?'))return;const r=await sb.rpc('tnt_save_task',{p_id:taskId,p_event:target.event_id,p_values:target,p_people:[...taskPeople(taskId),x.p.id]});if(r.error)return U.toast(r.error.message,true);U.closeModal(o);await loadAll();render();taskDetailModal(taskId);});}

function forgetOrgTask(id){const pending=[id];while(pending.length){const task=pending.pop();if(deletedOrgTasks.has(task))continue;deletedOrgTasks.add(task);S.tasks.filter(t=>t.parent_task_id===task).forEach(t=>pending.push(t.id));}pruneOrgState();}
function pruneOrgState(){
 S.events=S.events.filter(e=>!deletedOrgEvents.has(e.id));const events=new Set(S.events.map(e=>e.id));
 S.tasks=S.tasks.filter(t=>events.has(t.event_id)&&!t.archived_at&&!deletedOrgTasks.has(t.id));const tasks=new Set(S.tasks.map(t=>t.id));
 S.days=S.days.filter(d=>events.has(d.event_id));const days=new Set(S.days.map(d=>d.id));
 S.items=S.items.filter(i=>days.has(i.day_id)&&!i.archived_at&&!deletedOrgItems.has(i.id)&&(!i.task_id||tasks.has(i.task_id)));const items=new Set(S.items.map(i=>i.id));
 S.assignees=S.assignees.filter(a=>tasks.has(a.task_id));S.responsibles=S.responsibles.filter(r=>items.has(r.item_id));S.eventMembers=S.eventMembers.filter(m=>events.has(m.event_id));
 S.groups=S.groups.filter(g=>(!g.event_id||events.has(g.event_id))&&(!g.day_id||days.has(g.day_id)));const groups=new Set(S.groups.map(g=>g.id));S.groupMembers=S.groupMembers.filter(m=>groups.has(m.group_id));S.groupConfigs=S.groupConfigs.filter(g=>events.has(g.event_id));S.checkins=S.checkins.filter(c=>events.has(c.event_id));
 S.notifications=S.notifications.filter(n=>{if(n.event_id&&!events.has(n.event_id)||n.task_id&&!tasks.has(n.task_id))return false;const href=U.safeUrl(n.href);if(!href)return true;const q=new URL(href,location.origin).searchParams;return(!q.has('task')||tasks.has(q.get('task')))&&(!q.has('event')||events.has(q.get('event')));});
}
