function openQuickSchedule(){const next=S.events.filter(e=>e.kind==='saturday'&&e.status!=='cancelled'&&e.end_date>=today()).sort((a,b)=>a.start_date.localeCompare(b.start_date))[0];if(next)quickScheduleModal(S.selectedEvent&&eventBy(S.selectedEvent)?.status!=='cancelled'?S.selectedEvent:next.id);else navigateView('saturdays');}
function stepSaturday(step){const events=S.events.filter(e=>e.kind==='saturday'&&e.status!=='cancelled').sort((a,b)=>a.start_date.localeCompare(b.start_date)),index=events.findIndex(e=>e.id===S.selectedEvent),next=events[index+step];if(index<0||!next)return false;openSchedule(next.id);return true;}
let suppressScheduleClickUntil=0;
function bindScheduleSwipe(){
 const area=$('[data-schedule-swipe]');if(!area||eventBy(S.selectedEvent)?.kind!=='saturday')return;
 const app=$('#app');if(!app.dataset.scheduleCapture){app.dataset.scheduleCapture='1';app.addEventListener('click',e=>{if(Date.now()<suppressScheduleClickUntil&&e.target.closest('.schedule-swipe')){e.preventDefault();e.stopImmediatePropagation();}},true);}
 let start=null;area.addEventListener('pointerdown',e=>{if(e.isPrimary===false){start=null;return;}if(!['touch','pen'].includes(e.pointerType)||e.target.closest('.tnt-activity-swipe,button,input,select,textarea,a,label'))return;start={x:e.clientX,y:e.clientY,id:e.pointerId};});
 area.addEventListener('pointercancel',()=>start=null);area.addEventListener('pointerup',e=>{if(!start||e.pointerId!==start.id)return;const x=e.clientX-start.x,y=e.clientY-start.y;start=null;if(Math.abs(x)>=70&&Math.abs(x)>Math.abs(y)*1.7&&stepSaturday(x<0?1:-1)){suppressScheduleClickUntil=Date.now()+600;e.preventDefault();}});
}
