function quickScheduleModal(id){
 const e=eventBy(id);if(!e||e.status==='cancelled')return;const days=eventDays(id),tasks=programTasks(id),items=days.flatMap(d=>programDayItems(d.id)),waiting=pendingProgramTasks(id),coordinators=eventMembers(id).filter(m=>m.event_role==='organizer').map(m=>m.person_id);
 const activity=(record,date,task)=>{const ids=task?taskPeople(task.id):itemPeople(record.id),time=record.starts_at||task?.planned_start&&new Intl.DateTimeFormat('es-AR',{timeZone:'America/Argentina/Buenos_Aires',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(task.planned_start)),duration=record.duration_minutes||task?.duration_minutes,detail=record.description||task?.description,materials=record.materials||task?.materials;return `<article class="tnt-program-row ${task?.is_featured?'is-featured':''}" style="${featureStyle(task)}" data-tnt-record><div class="tnt-program-time ${time?'':'is-untimed'}"><b>${esc(time?fmtTime(time):canSeePlanningGaps(id)?'Sin horario':'')}</b><small>${duration?duration+' min':canSeePlanningGaps(id)?'Sin duración':''}</small></div><div class="tnt-program-detail"><h3>${esc(record.title)}</h3>${featuredBadge(task)}<span class="tnt-pill">${esc(task?STATUS_LABEL[task.status]||'Pendiente':RUN_LABEL[record.run_status]||'Pendiente')}</span>${detail?'<p>'+esc(detail)+'</p>':''}${materials?'<p><b>Materiales:</b> '+esc(materials)+'</p>':''}${record.location?'<p><b>Lugar:</b> '+esc(record.location)+'</p>':''}<div class="tnt-program-people">${ids.length?ids.map(pid=>`<span>${avatarHtml(pid)}<b>${esc(displayName(pid))}</b><small>Responsable</small></span>`).join(''):canSeePlanningGaps(id)?'<span class="tnt-unassigned">Sin responsable asignado</span>':''}</div>${isAdmin()||isEventOrganizer(id)?`<button class="btn" data-program-open="${task?'task|'+task.id:'item|'+record.id}">Ir a ver ${U.icon('arrow')}</button>`:''}</div></article>`;};
 modal(`${sheetHead('Cronograma rápido',e.name+' · '+fmtDate(e.start_date))}<section class="tnt-program-hero"><span class="eyebrow">EL EQUIPO EN ACCIÓN</span><h3>${esc(e.name)}</h3><p>${esc(e.location||'Lugar por confirmar')}</p><div class="tnt-program-coordinators">${coordinators.length?coordinators.map(pid=>`<span>${avatarHtml(pid)}<b>${esc(displayName(pid))}</b><small>Coordinación</small></span>`).join(''):canManagePeople(id)?'<p>Sin coordinadores asignados</p>':''}</div></section><div class="tnt-program">${days.map(d=>{const rows=programDayItems(d.id);return `<section><header><h3>${esc(d.label)}</h3><span>${fmtDate(d.date)}</span></header>${rows.map(i=>activity(i,d.date,taskBy(i.task_id))).join('')||'<p class="tiny">Todavía no hay actividades en este día.</p>'}</section>`;}).join('')}${waiting.length?'<section><header><h3>'+(canSeePlanningGaps(id)?'Por definir día u horario':'Más actividades')+'</h3></header>'+waiting.map(t=>activity(t,null,t)).join('')+'</section>':''}${!items.length&&!tasks.length?empty('Todavía no hay actividades','Creá la primera actividad desde el cronograma.') :''}</div><footer class="actions"><button class="btn" id="program-go">Abrir agenda ${U.icon('arrow')}</button>${canCreateActivity(id)?'<button class="btn primary" id="program-add">'+U.icon('plus')+' Nueva actividad</button>':''}</footer>`,true);
 $$('[data-program-open]').forEach(b=>b.onclick=()=>{const [kind,target]=b.dataset.programOpen.split('|');if(kind==='task')taskDetailModal(target);else scheduleItemDetailModal(target);});$('#program-go').onclick=async()=>{await closeModal();openSchedule(id);};$('#program-add')?.addEventListener('click',()=>taskEditModal(null,id));
}

function startOrgUpdates(){let busy=false;const refresh=async()=>{if(busy||document.hidden||TNT.blocked||window.TNTScheduleOrder?.busy)return;busy=true;const selected=S.selectedEvent;try{await loadAll();if(selected&&!eventBy(selected))clearOrgModal();render();}finally{busy=false;}};const timer=setInterval(refresh,30000);document.addEventListener('visibilitychange',refresh);window.addEventListener('focus',refresh);document.addEventListener('tnt:data',refresh);document.addEventListener('tnt:permissions',()=>{S.account=TNT.account;S.person=TNT.person;refresh();});window.addEventListener('pagehide',()=>{clearInterval(timer);document.removeEventListener('visibilitychange',refresh);window.removeEventListener('focus',refresh);document.removeEventListener('tnt:data',refresh);},{once:true});}


async function archiveActivities(ids,restore=false){
 const allowed=ids.filter(id=>{const t=taskBy(id);return restore||t&&canDeleteActivity(t.event_id);});if(!allowed.length)return;
 const r=await sb.rpc('tnt_archive_activities',{p_ids:allowed,p_restore:restore});if(r.error)return U.toast(r.error.message,true);const results=Array.isArray(r.data)?r.data:[],success=results.filter(x=>x.ok).map(x=>x.id),failed=results.filter(x=>!x.ok);
 if(!success.length)return U.toast(failed.map(x=>x.error).join(' · ')||'No se pudo eliminar la actividad.',true);
 if(!restore){const subtree=new Set(success);let changed=true;while(changed){changed=false;for(const t of S.tasks)if(subtree.has(t.parent_task_id)&&!subtree.has(t.id)){subtree.add(t.id);changed=true;}}for(const t of S.tasks)if(subtree.has(t.id))t.archived_at=new Date().toISOString();pruneOrgState();await closeModal();render();}
 await loadAll();render();if(!restore)TNTExperience.undo(success.length===1?'Actividad eliminada. Su historial está guardado.':success.length+' actividades eliminadas.',()=>archiveActivities(success,true));
 if(failed.length)U.toast(failed.length+' no se pudieron eliminar: '+failed.map(x=>x.error).join(' · '),true);
}
function bindActivitySwipes(){
 $$('.activity-card,.agenda-card').forEach(row=>{if(row.closest('.tnt-activity-swipe'))return;const itemId=row.querySelector('[data-item-open]')?.dataset.itemOpen,item=S.items.find(i=>i.id===itemId),task=taskBy(row.dataset.taskOpen||row.querySelector('[data-task-open]')?.dataset.taskOpen||item?.task_id),ev=task?.event_id||dayBy(item?.day_id)?.event_id;if(!ev||!canEditActivity(ev)&&!canDeleteActivity(ev))return;
  const wrapper=document.createElement('div');wrapper.className='tnt-activity-swipe';row.before(wrapper);wrapper.append(row);row.classList.add('tnt-swipe-front');
  const actions=document.createElement('div');actions.className='tnt-swipe-actions';actions.innerHTML=`${canEditActivity(ev)?'<button data-swipe-edit>'+U.icon('edit')+'<span>Editar</span></button>':''}${task&&canDeleteActivity(ev)?'<button data-swipe-delete>'+U.icon('trash')+'<span>Eliminar</span></button>':''}`;wrapper.append(actions);
  const more=document.createElement('button');more.className='tnt-swipe-more';more.type='button';more.setAttribute('aria-label','Opciones de la actividad');more.setAttribute('aria-expanded','false');more.innerHTML=U.icon('more');wrapper.append(more);more.onclick=()=>{const on=wrapper.classList.toggle('is-open');more.setAttribute('aria-expanded',String(on));};
  actions.querySelector('[data-swipe-edit]')?.addEventListener('click',()=>task?taskEditModal(task,ev):scheduleItemModal(item));actions.querySelector('[data-swipe-delete]')?.addEventListener('click',()=>archiveActivities([task.id]));
  let start=null,suppress=0;wrapper.addEventListener('pointerdown',e=>{if(e.isPrimary===false||e.target.closest('.tnt-swipe-actions,.tnt-swipe-more,[data-schedule-drag],[data-task-team],[data-feature-task],input,select,textarea'))return;start={x:e.clientX,y:e.clientY,id:e.pointerId};});wrapper.addEventListener('pointercancel',()=>{start=null;});wrapper.addEventListener('pointerup',e=>{if(!start||e.pointerId!==start.id)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;start=null;if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy)*1.5){wrapper.classList.toggle('is-open',dx<0);more.setAttribute('aria-expanded',String(dx<0));suppress=Date.now()+600;e.preventDefault();}});wrapper.addEventListener('click',e=>{if(Date.now()<suppress&&!e.target.closest('.tnt-swipe-actions,.tnt-swipe-more')){e.preventDefault();e.stopImmediatePropagation();}},true);
 });
 if(S.view==='schedule'&&eventBy(S.selectedEvent)&&canDeleteActivity(S.selectedEvent)){const target=$('.schedule-top .actions');if(target&&!target.querySelector('[data-bulk-activities]')){const b=document.createElement('button');b.className='btn';b.dataset.bulkActivities='';b.textContent='Seleccionar varias';b.onclick=bulkActivities;target.append(b);}}
}
function bindScheduleOrder(){
 if(!window.TNTScheduleOrder)return;
 document.querySelectorAll('[data-order-day]').forEach(list=>{
  const day=dayBy(list.dataset.orderDay);if(!day||!canEditActivity(day.event_id)||programDayItems(day.id).length<2)return;
  list.querySelectorAll('[data-schedule-item]').forEach(card=>{
   const id=card.dataset.scheduleItem,item=S.items.find(i=>i.id===id),row=card.closest('.tnt-activity-swipe')||card;
   row.dataset.scheduleOrderItem=id;
   const button=document.createElement('button');button.type='button';button.className='schedule-drag-handle';button.dataset.scheduleDrag=id;
   button.setAttribute('aria-label','Mover '+item.title+'. Flecha arriba o abajo para cambiar su lugar.');button.title='Arrastrar para ordenar';
   button.innerHTML='<svg class="tnt-icon" viewBox="0 0 24 24" aria-hidden="true" fill="currentColor">'+[5,12,19].flatMap(y=>[8,16].map(x=>'<circle cx="'+x+'" cy="'+y+'" r="1.7"/>')).join('')+'</svg>';
   card.querySelector('.agenda-time').append(button);
  });
  TNTScheduleOrder.bind(list,{
   snapshot:()=>dayItems(day.id).map(i=>({id:i.id,starts_at:i.starts_at||null,duration_minutes:i.duration_minutes??null,sort_order:i.sort_order??0,task_id:i.task_id||null})),
   validate:ids=>TNTScheduleOrder.validOrder(ids.map(id=>S.items.find(i=>i.id===id)).filter(Boolean)),
   onBlocked:()=>{const hint=list.parentElement.querySelector('.schedule-order-hint');if(hint)hint.textContent='Ese lugar invertiría dos horarios. Las actividades con hora definida mantienen su orden; las que no tienen hora se pueden mover libremente.';},
   onSave:async(ids,before)=>{
    const allIds=[...ids,...dayItems(day.id).filter(i=>!ids.includes(i.id)).map(i=>i.id)];
    const r=await sb.rpc('tnt_reorder_program',{p_day:day.id,p_ids:allIds,p_before:before});if(r.error)throw r.error;
    const saved=r.data?.items||[],savedIds=new Set(saved.map(i=>i.id));S.items=S.items.filter(i=>!savedIds.has(i.id)).concat(saved);
    for(const item of saved){const task=taskBy(item.task_id);if(task)task.sort_order=item.sort_order;}
    await loadAll();toast('Orden guardado. Los horarios se mantienen.');
   },
   onError:async error=>{toast(errMsg(error),true);await loadAll();},onSettled:()=>render()
  });
 });
}

function bulkActivities(){const e=eventBy(S.selectedEvent),rows=eventTasks(e.id);const o=U.modal('Actividades de '+e.name,`<p>Elegí las actividades que querés eliminar. Se conserva su historial y podés deshacer la acción.</p><form class="tnt-form" id="bulk-activities"><label><input type="checkbox" data-select-all> Seleccionar todas</label>${rows.map(t=>`<label class="tnt-bulk-row"><input name="activity" type="checkbox" value="${t.id}"><span><b>${esc(t.title)}</b><small>${taskPeople(t.id).map(displayName).join(', ')||'Sin responsable'}</small></span></label>`).join('')}<button class="tnt-button primary">Eliminar seleccionadas</button><p role="status"></p></form>`);o.querySelector('[data-select-all]').onchange=e=>o.querySelectorAll('[name=activity]').forEach(c=>c.checked=e.target.checked);o.querySelector('form').onsubmit=async event=>{event.preventDefault();const ids=[...o.querySelectorAll('[name=activity]:checked')].map(c=>c.value);if(!ids.length)return;o.querySelector('[type=submit]').disabled=true;await U.closeModal(o);await archiveActivities(ids);};}

boot();
